local Singleton = import('Frame.Singleton')

local gameUtils = GameUtils
local parseUtils = CS.ParseUtils
---@class BattleMgr
---@field GetInstance fun(self:BattleMgr):BattleMgr
local BattleMgr = Class("BattleMgr", Singleton)

---SendBattleEnd
---传递战斗结果
---@param isPass number
---@param lossHp string
function BattleMgr:SendBattleEnd(isPass)

    local data = {}
    data["isPassed"] = checkString(isPass)
    --data["cardsHealth"] =checkString(healthStr)
    gameUtils.Request(Interfaces.QuestGrade, data, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            local rewards = {
                { goodsId = Constants.Currency.HpId, num = checkNumber(responseData.hp) - GoodsUtils.GetThingNo(Constants.Currency.HpId) },
                { goodsId = Constants.Currency.GoldId, num = checkNumber(responseData.gold) - GoodsUtils.GetThingNo(Constants.Currency.GoldId) },
                { goodsId = Constants.Currency.FreeDiamondId, num = checkNumber(responseData.freeDiamond) - GoodsUtils.GetThingNo(Constants.Currency.FreeDiamondId) },
            }
            GoodsUtils.DrawRewards(rewards)
            if isSet(responseData, "rewards") then
                GoodsUtils.DrawRewards(responseData.rewards)
                self:RefreashReward(responseData.rewards,0)
            end
        end
    end)
end


---SendBattleEnd
---传递战斗结果属性本
---@param isPass number
---@param lossHp string
function BattleMgr:SendBattleEndProp(isPass)
    local data = {}
    data["isPassed"] = checkString(isPass)
    --data["cardsHealth"] =checkString(healthStr)
    gameUtils.Request(Interfaces.AttrQuestGrade, data, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            if isSet(responseData, "rewards") then
                GoodsUtils.DrawRewards(responseData.rewards)
                self:RefreashReward(responseData.rewards,1)
            end
        end
    end)
end

---SendBattleEnd
---传递战斗结果奖励并显示
---@param rewards table
---@param ispropID number
function BattleMgr:RefreashReward(rewards, ispropID)
    local GameObject = CS.UnityEngine.GameObject
    local ParentObj=GameObject.Find("achorBattleEndRward")
    local nodeLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/GoodNode.prefab")
    rewards = checkTable(rewards)
    if table.count(rewards) > 0 then
        for i, v in pairs(rewards) do
            local reward = rewards[i]
            local goodsIdT = checkNumber(reward.goodsId)
            local num = checkNumber(reward.num)
            local go = nodeLoader:Instantiate()
            CS.Engine.Lib.KTool.SetActive(go, true)
            CS.Engine.Lib.KTool.SetParent(go, ParentObj, false)
            --go:GetComponent(typeof(Image)).raycastTarget = false
            local GoodNodeMBPath = "Game.Behaviours.GoodNodeMB"
            local goodNodes = GetLuaBehaviour(go, GoodNodeMBPath)
            if not isNull(goodNodes) then
                goodNodes.Env:Reload({ goodsId =goodsIdT,
                                       isShowNo = true, text = tostring(num)
                })
            end
        end
    end
    nodeLoader:Release()
    -- if isNotify then
    --     ---@type Event
    --     Events.Broadcast(Constants.EventNames.EveryThingChangeEventName, checkNumber(goodsId))
    -- end
end



--[[
请求服务器 创建属性副本界面
--]]
function BattleMgr:ShowPropQuestEntryView()
    -- 请求服务器
    local UIModule = CS.Engine.UI.UIModule
    GameUtils.Request(
            Interfaces.AttrQuestHome, nil,
            function(request, response)
                local data = checkTable(response.data)
                GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {{ id=Constants.UITypeIds.UIPropQuestEntryDialog, parameters = data}})
            end
    )
end

return BattleMgr